import{_ as r}from"./chunks/panel-workspace.DfVZw37W.js";import{_ as i,a as d,b as n}from"./chunks/theme-dark.DMCpB48j.js";import{_ as s,C as l,o as g,c,a2 as a,j as m,a as t,E as h}from"./chunks/framework.Dx-TCpNt.js";const k=JSON.parse('{"title":"はじめに","description":"KomaYomi（Manga Learner）は、漫画で言語を学ぶためのローカル優先の Web アプリです。同じページを日本語・中国語・英語で持ち、ページをコマに分割し、コマを並べて読み、そのコマに結び付いた Markdown ノートを書けます。","frontmatter":{"description":"KomaYomi（Manga Learner）は、漫画で言語を学ぶためのローカル優先の Web アプリです。同じページを日本語・中国語・英語で持ち、ページをコマに分割し、コマを並べて読み、そのコマに結び付いた Markdown ノートを書けます。"},"headers":[],"relativePath":"ja/guide/introduction.md","filePath":"ja/guide/introduction.md","lastUpdated":1794727111000}'),u={name:"ja/guide/introduction.md"};function p(f,o,_,b,v,j){const e=l("Badge");return g(),c("div",null,[o[2]||(o[2]=a('<h1 id="はじめに" tabindex="-1">はじめに <a class="header-anchor" href="#はじめに" aria-label="Permalink to &quot;はじめに&quot;">​</a></h1><p>KomaYomi（<strong>Manga Learner</strong>）は、漫画で言語を学ぶためのローカル優先の Web アプリです。同じページを日本語・中国語・英語で持ち、ページをコマに分割し、コマを並べて読み、そのコマに結び付いた Markdown ノートを書けます。</p><p>気軽な読書のための漫画リーダーではなく、配信プラットフォームでもありません。すべては自分のマシン上で、自分の画像フォルダを対象に動作します。</p><h2 id="解決する課題" tabindex="-1">解決する課題 <a class="header-anchor" href="#解決する課題" aria-label="Permalink to &quot;解決する課題&quot;">​</a></h2><p>翻訳は、ページ単位よりもコマ単位で学ぶほうが理解しやすいものです。しかし、同じ本のスキャンを3言語でそろえるのは簡単ではありません。ページがずれ、コマの切り出しが異なり、文字の位置も違います。通常の画像ビューアでは、ズームは1段階だけで、ノートも取れず、「この吹き出しをこの3つの版で」と指定する方法もありません。</p><p>KomaYomi は、その間に欠けている層を追加します。</p><ol><li><strong>構造</strong> — コマは正規化された矩形として検出・保存されるため、ズームやエクスポートのサイズに左右されません。</li><li><strong>位置合わせ</strong> — 言語ごとに個別にずらせるため、同じコマを本当に重ねられます。</li><li><strong>ノート</strong> — すべての所見はページまたはコマに紐付き、タグと出典付きの Markdown で残せます。</li></ol><h2 id="_5ステップのワークフロー" tabindex="-1">5ステップのワークフロー <a class="header-anchor" href="#_5ステップのワークフロー" aria-label="Permalink to &quot;5ステップのワークフロー&quot;">​</a></h2><table tabindex="0"><thead><tr><th>手順</th><th>行うこと</th><th>ページ</th></tr></thead><tbody><tr><td>1</td><td>画像を <code>raw/&lt;volume&gt;/&lt;language&gt;/&lt;chapter&gt;/01.jpg</code> に配置するか、既存のフォルダを追加します。</td><td><a href="/KomaYomi-docs/ja/guide/gallery">ライブラリとインポート</a></td></tr><tr><td>2</td><td>ページを開いて自動分割を実行し、枠を手作業で修正します。</td><td><a href="/KomaYomi-docs/ja/guide/panels">コマ分割ワークベンチ</a></td></tr><tr><td>3</td><td>2〜3言語を並列または重ね表示で読み、位置合わせを行い、確認したい言語をマスクします。</td><td><a href="/KomaYomi-docs/ja/guide/compare">比較リーダー</a></td></tr><tr><td>4</td><td>タグ、出典、スクリーンショット付きのページノートとコマノートを書きます。</td><td><a href="/KomaYomi-docs/ja/guide/notes">ノート</a></td></tr><tr><td>5</td><td>学習用 HTML、スライド用 PNG、別のマシン用のプロジェクトパッケージをエクスポートします。</td><td><a href="/KomaYomi-docs/ja/guide/export">エクスポート</a></td></tr></tbody></table><h2 id="画面の構成" tabindex="-1">画面の構成 <a class="header-anchor" href="#画面の構成" aria-label="Permalink to &quot;画面の構成&quot;">​</a></h2><figure class="shot"><img src="'+r+'" alt="漫画ページ、検出されたコマ、リサイズハンドル、注釈ツールバーを表示したコマ分割ワークベンチ"><figcaption>コマ分割ワークベンチ。上部バー：ページ移動、コマ / 比較読み、読み順、テーマ、表示言語、ノート、エクスポート。左：ライブラリ。右：ノート。中央：コマ枠付きのページ。</figcaption></figure><p>ウィンドウには、常に同じ位置にある5つの領域があります。</p><ul><li><strong>上部バー</strong> — ブランド（ライブラリに戻る）、巻 / 話 / ページ、<code>‹</code> <code>›</code> のページ矢印、保存インジケーター、<strong>コマ / 比較読み</strong> の切り替え、読み順のセレクター、UI テーマ、表示言語、<strong>ノート</strong>、<strong>エクスポート</strong>。</li><li><strong>ライブラリサイドバー</strong>（<code>S</code>） — 巻 → 話 → ページ。ページごとの警告に加え、マンガの追加、フォルダ規則、プロジェクトファイル、交換ファイル、バックアップへの入口があります。</li><li><strong>ステージ</strong> — 表示の切り替えに応じて、コマ分割ワークベンチまたは比較リーダーを表示します。</li><li><strong>ノート列</strong>（<code>N</code>） — ページノート、コマノート、一覧検索、一時メモ。</li><li><strong>ペインスプリッター</strong> — ライブラリとステージの間、またはステージとノートの間の縦ハンドルをドラッグしてサイズを変更します。ダブルクリックで既定値に戻ります。</li></ul><p>ページは1〜3言語を持てます。比較リーダーの言語チップは、現在のページに存在する言語だけが有効になります。</p><h2 id="最初の10分" tabindex="-1">最初の10分 <a class="header-anchor" href="#最初の10分" aria-label="Permalink to &quot;最初の10分&quot;">​</a></h2><ol><li>アプリを起動し（<code>npm run dev</code> またはデスクトップ版）、<code>http://127.0.0.1:5173</code> を開きます。</li><li><code>raw/</code> に1巻分を置くか、サイドバーの <strong>＋ マンガを追加</strong> をクリックして既存のフォルダを指定します。</li><li>サイドバーでページをクリックします。初回表示時にコマの自動検出が実行され、結果が <code>data/pages/</code> に保存されます。</li><li><strong>比較読み</strong>（<code>C</code>）に切り替え、<code>JA</code> と <code>ZH</code> を選び、コマがそろうまでペインをドラッグします。</li><li><strong>ノート</strong>（<code>N</code>）を開いてコマを選択し、最初のノートを書きます。<code>Ctrl+Enter</code> で保存します。</li><li><code>E</code> を押して HTML をエクスポートし、ブラウザで開きます。</li></ol><h2 id="実装済みの機能" tabindex="-1">実装済みの機能 <a class="header-anchor" href="#実装済みの機能" aria-label="Permalink to &quot;実装済みの機能&quot;">​</a></h2><div class="status-list"><div><strong>ライブラリ</strong> — 巻をスキャンし、言語フォルダの別名を認識し、ページを並び順で対応付け、欠けているページや命名の不一致を警告します。</div><div><strong>コマ</strong> — XY カットによる自動検出、追加 / 移動 / 8方向のリサイズ / 結合 / 削除、番号付け、パーセント入力、グリッド生成、コマテンプレート、宣言的レイアウト、プラグイン。</div><div><strong>注釈</strong> — 矢印、矩形、楕円、マーカー、フリーハンドペン、テキスト、番号バッジ、モザイク、ページ単位の表示切り替え、PNG エクスポート対応。</div><div><strong>比較</strong> — 2〜3言語、並列または重ね表示、言語ごとのぼかし / 塗りつぶしマスク、ホイールズーム、パン、ページ / コマ / アンカー / グリッドの位置合わせ、保存済みプリセット、言語順のカスタマイズ。</div><div><strong>ノート</strong> — ページ / コマのノート、ツールバーとライブプレビュー付きの Markdown、タグ、出典、添付画像、一覧検索、LLM 用コピー、一時メモ。</div><div><strong>エクスポート</strong> — HTML（画像フォルダまたは単一ファイル）、PNG（ページ全体、現在のコマ、3言語コラージュ）、コマ枠の重ね描き、印刷用スタイル、エクスポートテンプレート。</div><div><strong>ストレージ</strong> — ローカルフォルダ、マウントしたネットワーク共有、WebDAV。オンデマンドの画像取得と上限付き LRU キャッシュに対応します。</div><div><strong>可搬性</strong> — `.mnproj` プロジェクトパッケージ、`.mntpl` / `.mnexp` / `.mnpage.json` の交換ファイル、バックアップと復元の ZIP、バージョン付きスキーマ。</div></div><h2 id="未実装の機能" tabindex="-1">未実装の機能 <a class="header-anchor" href="#未実装の機能" aria-label="Permalink to &quot;未実装の機能&quot;">​</a></h2>',19)),m("p",null,[o[0]||(o[0]=t("以下の項目は、登場する箇所で ",-1)),h(e,{type:"warning",text:"予定"}),o[1]||(o[1]=t(" と表示されます。",-1))]),o[3]||(o[3]=a('<ul><li>PDF、Word（<code>.docx</code>）、語彙リストのエクスポート。</li><li>オフラインの書き込みキューと定期的な自動バックアップ。</li><li>アプリ内でのコマグループの作成と編集。JSON フィールドは存在し、読み書き・インポート・エクスポートで保持されますが、編集 UI はまだありません。</li><li>ネイティブのモバイルアプリ。Web UI は狭いブラウザウィンドウでも動作します（下記参照）。</li></ul><figure class="shot"><img src="'+i+'" alt="言語ペインが縦に積み重なった、狭いウィンドウの比較リーダー"><figcaption>狭いウィンドウ：ペインは縦に積み重なり、ライブラリはドロワーになります。これはレスポンシブな Web レイアウトであり、ネイティブアプリではありません。</figcaption></figure><h2 id="ライトとダーク" tabindex="-1">ライトとダーク <a class="header-anchor" href="#ライトとダーク" aria-label="Permalink to &quot;ライトとダーク&quot;">​</a></h2><p>UI テーマは既定でシステムに従い、上部バーからライトまたはダークに固定できます。エクスポートされる HTML はライトテーマのみなので、スクリーンショットや印刷結果が一定になります。</p><figure class="shot"><img src="'+d+'" alt="ライトテーマの比較リーダー"><figcaption>ライトテーマ。</figcaption></figure><figure class="shot"><img src="'+n+'" alt="ダークテーマの比較リーダー"><figcaption>ダークテーマ。</figcaption></figure><h2 id="よくある落とし穴" tabindex="-1">よくある落とし穴 <a class="header-anchor" href="#よくある落とし穴" aria-label="Permalink to &quot;よくある落とし穴&quot;">​</a></h2><ul><li><strong>ライブラリに何も出ない。</strong> サイドバーは <code>raw/</code> だけを走査します。先にフォルダーを追加するか、リモートツリーをマウントしてください。<a href="/KomaYomi-docs/ja/guide/gallery">ライブラリと取り込み</a> を参照。</li><li><strong>最初のページのコマがずれている。</strong> 自動検出は下書きで、結論ではありません。コマ単位のノートを書く前に枠を直してください。あとで再検出すると手作業の修正は失われます。</li><li><strong>言語チップが灰色。</strong> そのページにその言語の画像がありません。ページ数と言語の対応付けを確認してください。</li><li><strong>別のマシンでノートが消えたように見える。</strong> ノートは <code>data/</code>、画像は <code>raw/</code> にあります。両方を移すか、<code>.mnproj</code> を書き出してください。<a href="/KomaYomi-docs/ja/guide/project-files">プロジェクトファイルと形式</a> を参照。</li><li><strong>オフラインで画像取得に失敗する。</strong> オフライン前に開いたページだけがキャッシュされています。<a href="/KomaYomi-docs/ja/guide/remote">バックアップとリモート</a> を参照。</li></ul><h2 id="次に読む" tabindex="-1">次に読む <a class="header-anchor" href="#次に読む" aria-label="Permalink to &quot;次に読む&quot;">​</a></h2><ul><li>新規インストール：<a href="/KomaYomi-docs/ja/guide/installation">インストールと起動</a>。</li><li>画像を追加する：<a href="/KomaYomi-docs/ja/guide/gallery">ライブラリと取り込み</a>。</li><li>キーを探す：<a href="/KomaYomi-docs/ja/guide/shortcuts">ショートカット一覧</a>。</li><li>問題が起きた：<a href="/KomaYomi-docs/ja/faq">FAQ とトラブルシューティング</a>。</li></ul>',10))])}const T=s(u,[["render",p]]);export{k as __pageData,T as default};
